function RenameButton() {
  const mutation = useMutation({
    mutationFn: updateUser,

    onMutate: (variables) => {
      return {
        rollback: () => mutation.mutate({ id: 1, name: 'Alice' }),
        disabledButton: isPending,
      }
    },
  })

  return (
    <button disabled={mutation.isPending}>
      Rename
    </button>
  )
}

